Definition mk_1RB0LD_1LC1RA_1RD0LD_0RB1LD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LD_1LC1RA_1RD0LD_0RB1LD.

(** 1RB0LD_1LC1RA_1RD0LD_0RB1LD *)
(** 1RB0LD_1LC1RA_1RD0LD_0RB1LD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LD_1LC1RA_1RD0LD_0RB1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S1 DL StD end.

(** Its mirror 1LB0RD_1RC1LA_1LD0RD_0LB1RD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S1 DR StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LD_1LC1RA_1RD0LD_0RB1LD : list Instr := [(StC, S0)].
Definition tmw_1RB0LD_1LC1RA_1RD0LD_0RB1LD : TM := tm_wrap_trs tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD pins_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
Local Notation tm := tmw_1RB0LD_1LC1RA_1RD0LD_0RB1LD.

Lemma mirror_ok_1RB0LD_1LC1RA_1RD0LD_0RB1LD : mirror_tm tm_1RB0LD_1LC1RA_1RD0LD_0RB1LD = tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LD_1LC1RA_1RD0LD_0RB1LD (p : positive) : cconf := (StD, (Jp p ++ [S0;S1;S0], S0, [])).
Local Notation Cc := Cc_1RB0LD_1LC1RA_1RD0LD_0RB1LD.

(** ** The certificate *)

Definition A0_1RB0LD_1LC1RA_1RD0LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
