Lemma run_int_1RB0LD_1LC1RA_1RD0LD_0RB1LD : srun tm false true chi_1RB0LD_1LC1RA_1RD0LD_0RB1LD A0_1RB0LD_1LC1RA_1RD0LD_0RB1LD = Some (A1_1RB0LD_1LC1RA_1RD0LD_0RB1LD, 4, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0LD_1LC1RA_1RD0LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S0;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB0LD_1LC1RA_1RD0LD_0RB1LD : sconf := mkC StD (mkS [] [S1;S1] 1 1 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition cho_1RB0LD_1LC1RA_1RD0LD_0RB1LD : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 3; SWinL 5; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_ovf_1RB0LD_1LC1RA_1RD0LD_0RB1LD : srun tm true true cho_1RB0LD_1LC1RA_1RD0LD_0RB1LD B0_1RB0LD_1LC1RA_1RD0LD_0RB1LD = Some (B1_1RB0LD_1LC1RA_1RD0LD_0RB1LD, 4, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0;S1;S0]) [] j A0_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB0LD_1LC1RA_1RD0LD_0RB1LD, cden, A0_1RB0LD_1LC1RA_1RD0LD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S0;S1;S0]) [] j A1_1RB0LD_1LC1RA_1RD0LD_0RB1LD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB0LD_1LC1RA_1RD0LD_0RB1LD, cden, A1_1RB0LD_1LC1RA_1RD0LD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0LD_1LC1RA_1RD0LD_0RB1LD A0_1RB0LD_1LC1RA_1RD0LD_0RB1LD A1_1RB0LD_1LC1RA_1RD0LD_0RB1LD 4 4
             run_int_1RB0LD_1LC1RA_1RD0LD_0RB1LD (Jp q0 ++ [S0;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j q0 E).
Qed.

Lemma gso_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB0LD_1LC1RA_1RD0LD_0RB1LD, cden, B0_1RB0LD_1LC1RA_1RD0LD_0RB1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LD_1LC1RA_1RD0LD_0RB1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LD_1LC1RA_1RD0LD_0RB1LD
             = (StD, (rep [S1;S1] (S j) ++ [S1;S0;S1], S0, []))).
  { unfold cden, B1_1RB0LD_1LC1RA_1RD0LD_0RB1LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S1] (S j) ++ [S1;S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0LD_1LC1RA_1RD0LD_0RB1LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0LD_1LC1RA_1RD0LD_0RB1LD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LD_1LC1RA_1RD0LD_0RB1LD B0_1RB0LD_1LC1RA_1RD0LD_0RB1LD B1_1RB0LD_1LC1RA_1RD0LD_0RB1LD 4 10 p j' [] []).
    + exact run_ovf_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j' E).
    + exact (geo_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0LD_1LC1RA_1RD0LD_0RB1LD : stepn tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD 12 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD 12 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD 12 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0LD_1LC1RA_1RD0LD_0RB1LD : existsb (fun tg => cfires tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD c0 12 tg) pins_1RB0LD_1LC1RA_1RD0LD_0RB1LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LD_1LC1RA_1RD0LD_0RB1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0LD_1LC1RA_1RD0LD_0RB1LD = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j (Jp q0 ++ [S0;S1;S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0LD_1LC1RA_1RD0LD_0RB1LD p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LD_1LC1RA_1RD0LD_0RB1LD : forall t, ~ In t pins_1RB0LD_1LC1RA_1RD0LD_0RB1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LD_1LC1RA_1RD0LD_0RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB0LD_1LC1RA_1RD0LD_0RB1LD (StA, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB0LD_1LC1RA_1RD0LD_0RB1LD [SRotL 1; SWin 1; SCycL 2 0; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LD_1LC1RA_1RD0LD_0RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LD_1LC1RA_1RD0LD_0RB1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LD_1LC1RA_1RD0LD_0RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LD_1LC1RA_1RD0LD_0RB1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LD_1LC1RA_1RD0LD_0RB1LD
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 3; SWinL 3]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0LD_1LC1RA_1RD0LD_0RB1LD : NonHalt tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD /\ QHBoundTr 32779478 tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD /\ QuasiHaltsTr tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
Proof.
  apply (lap_qh_stage tmm_1RB0LD_1LC1RA_1RD0LD_0RB1LD pins_1RB0LD_1LC1RA_1RD0LD_0RB1LD Cc 1 12 32779478).
  - exact bootq_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
  - intros p _. apply lap_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
  - intros t Ht p _. apply fire_1RB0LD_1LC1RA_1RD0LD_0RB1LD. exact Ht.
  - exact wit_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
  - apply qcleb_QC_13. reflexivity.
Qed.

Theorem qhtr_1RB0LD_1LC1RA_1RD0LD_0RB1LD : NonHalt tm_1RB0LD_1LC1RA_1RD0LD_0RB1LD /\ QHBoundTr 32779478 tm_1RB0LD_1LC1RA_1RD0LD_0RB1LD /\ QuasiHaltsTr tm_1RB0LD_1LC1RA_1RD0LD_0RB1LD.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0LD_1LC1RA_1RD0LD_0RB1LD). rewrite mirror_ok_1RB0LD_1LC1RA_1RD0LD_0RB1LD. exact qhtrm_1RB0LD_1LC1RA_1RD0LD_0RB1LD. Qed.

End B_QC_13_014.

