Lemma fire_1RB0LD_1LC1RA_1RD1LB_0RA1LD : forall t, ~ In t pins_1RB0LD_1LC1RA_1RD1LB_0RA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
