    apply (lap_of_run tm Cc true true cho_1RB0LD_1RC0LD_1LA1RB_0RB1LD B0_1RB0LD_1RC0LD_1LA1RB_0RB1LD B1_1RB0LD_1RC0LD_1LA1RB_0RB1LD 4 14 p j' [] []).
    + exact run_ovf_1RB0LD_1RC0LD_1LA1RB_0RB1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LD_1RC0LD_1LA1RB_0RB1LD p j' E).
    + exact (geo_1RB0LD_1RC0LD_1LA1RB_0RB1LD p j' E).
