  apply (fire_of_run_instr tm Cc true true l B0_1RB0LD_1RC0LD_1LA1RB_0RC1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LD_1RC0LD_1LA1RB_0RC1LD p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
