    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LD_1RC____1LD1RA_0RB0LD [SCycL 3 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
