    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RA_1LC1LD_1RC0LD_0LC1RA = Some t ->
