    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RA_1LC1LD_1RC0LD_0LC1RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RA_1LC1LD_1RC0LD_0LC1RA : forall t, ~ In t pins_1RB0RA_1LC1LD_1RC0LD_0LC1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RA_1LC1LD_1RC0LD_0LC1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA
      with (l := [SCycL 4 0; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA
      with (l := [SCycL 4 0; SWin 4; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA
      with (l := [SCycL 4 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA
      with (l := [SCycL 4 0; SWin 4; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA
      with (l := [SCycL 4 0; SWin 4; SWinL 3]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RA_1LC1LD_1RC0LD_0LC1RA
      with (l := [SCycL 4 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

