  apply (lap_qh_stage tm_1RB0RB_0LC0RA_1LD1RC_1RA1LC pins_1RB0RB_0LC0RA_1LD1RC_1RA1LC Cc 1 3 32779478).
  - exact bootq_1RB0RB_0LC0RA_1LD1RC_1RA1LC.
  - intros p _. apply lap_1RB0RB_0LC0RA_1LD1RC_1RA1LC.
  - intros t Ht p _. apply fire_1RB0RB_0LC0RA_1LD1RC_1RA1LC. exact Ht.
  - exact wit_1RB0RB_0LC0RA_1LD1RC_1RA1LC.
  - apply qcleb_QC_13. reflexivity.
