  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB0RB_0LC0RB_1LD1RC_1RA1LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RB_0LC0RB_1LD1RC_1RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_0LC0RB_1LD1RC_1RA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_0LC0RB_1LD1RC_1RA1LC B0_1RB0RB_0LC0RB_1LD1RC_1RA1LC B1_1RB0RB_0LC0RB_1LD1RC_1RA1LC 4 8 p j' [] []).
    + exact run_ovf_1RB0RB_0LC0RB_1LD1RC_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_0LC0RB_1LD1RC_1RA1LC p j' E).
    + exact (geo_1RB0RB_0LC0RB_1LD1RC_1RA1LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RB_0LC0RB_1LD1RC_1RA1LC : stepn tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC 3 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RB_0LC0RB_1LD1RC_1RA1LC : existsb (fun tg => cfires tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC c0 3 tg) pins_1RB0RB_0LC0RB_1LD1RC_1RA1LC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0LC0RB_1LD1RC_1RA1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0LC0RB_1LD1RC_1RA1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_0LC0RB_1LD1RC_1RA1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_0LC0RB_1LD1RC_1RA1LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0LC0RB_1LD1RC_1RA1LC : forall t, ~ In t pins_1RB0RB_0LC0RB_1LD1RC_1RA1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0LC0RB_1LD1RC_1RA1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC0RB_1LD1RC_1RA1LC [SCycL 2 0; SWin 2; SWinL 2] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC0RB_1LD1RC_1RA1LC [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC0RB_1LD1RC_1RA1LC [SCycL 2 0; SWin 2; SWinL 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC0RB_1LD1RC_1RA1LC [] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC0RB_1LD1RC_1RA1LC [SCycL 2 0; SWin 2; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC0RB_1LD1RC_1RA1LC [SCycL 2 0; SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtr_1RB0RB_0LC0RB_1LD1RC_1RA1LC : NonHalt tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC /\ QHBoundTr 32779478 tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC /\ QuasiHaltsTr tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC.
Proof.
  apply (lap_qh_stage tm_1RB0RB_0LC0RB_1LD1RC_1RA1LC pins_1RB0RB_0LC0RB_1LD1RC_1RA1LC Cc 1 3 32779478).
  - exact bootq_1RB0RB_0LC0RB_1LD1RC_1RA1LC.
  - intros p _. apply lap_1RB0RB_0LC0RB_1LD1RC_1RA1LC.
  - intros t Ht p _. apply fire_1RB0RB_0LC0RB_1LD1RC_1RA1LC. exact Ht.
  - exact wit_1RB0RB_0LC0RB_1LD1RC_1RA1LC.
  - apply qcleb_QC_13. reflexivity.
Qed.

